import{_ as l,I as t,c as n,o,a5 as s,j as a,J as i}from"./chunks/framework.BtqC3pLB.js";const g=JSON.parse('{"title":"日本 -> 埼玉 -> 秩父 -> 秩父","description":"","frontmatter":{},"headers":[],"relativePath":"日本/埼玉/秩父/index.md","filePath":"docs/日本/埼玉/秩父/index.md","lastUpdated":1787977155000}'),h={name:"日本/埼玉/秩父/index.md"};function d(c,e,u,f,p,m){const r=t("PreviewLink");return o(),n("div",null,[e[0]||(e[0]=s('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /日本/埼玉/秩父.md for this page in Markdown format</div><h1 id="秩父" tabindex="-1">秩父 <a class="header-anchor" href="#秩父" aria-label="Permalink to “秩父”">​</a></h1><h2 id="東京近郊的山城與祭典之鄉" tabindex="-1">東京近郊的山城與祭典之鄉 <a class="header-anchor" href="#東京近郊的山城與祭典之鄉" aria-label="Permalink to “東京近郊的山城與祭典之鄉”">​</a></h2><p>秩父位於埼玉縣西部的山間盆地，從東京出發可安排一日遊，也適合以溫泉、戶外活動與地方美食為主題停留數日。市區以秩父神社和老街為中心，郊區則有羊山公園、武甲山與三峯神社等景點。</p><h2 id="必訪景點" tabindex="-1">必訪景點 <a class="header-anchor" href="#必訪景點" aria-label="Permalink to “必訪景點”">​</a></h2><ul><li><strong><a href="./景點/秩父神社">秩父神社</a>：</strong> 欣賞精緻雕刻，認識秩父地方信仰與秩父夜祭。</li><li><strong><a href="./景點/羊山公園">羊山公園</a>：</strong> 春季可觀賞芝櫻之丘，並眺望武甲山與秩父市區。</li><li><strong><a href="./景點/三峯神社">三峯神社</a>：</strong> 位於約 1,100 公尺山區的古老神社，適合搭配山景與健行行程。</li><li><strong><a href="./景點/溫泉">溫泉</a>：</strong> 從西武秩父站前的日歸溫泉，到奧長瀞溪谷旁的露天溫泉，適合安排在景點行程後放鬆。</li><li><strong><a href="./景點/長瀞">長瀞</a>：</strong> 欣賞荒川岩畳、搭乘溪谷遊船，並參拜寶登山神社。</li></ul><h2 id="鄰近季節景點" tabindex="-1">鄰近季節景點 <a class="header-anchor" href="#鄰近季節景點" aria-label="Permalink to “鄰近季節景點”">​</a></h2><ul><li><strong><a href="./景點/巾著田曼珠沙華公園">巾著田曼珠沙華公園</a>：</strong> 秋季可前往日高市巾著田，欣賞約 500 萬株曼珠沙華形成的紅色花海。</li></ul><h2 id="交通資訊" tabindex="-1">交通資訊 <a class="header-anchor" href="#交通資訊" aria-label="Permalink to “交通資訊”">​</a></h2><ul><li><strong><a href="./交通/">前往秩父與市內交通</a>：</strong> 整理西武鐵道、秩父鐵道與前往三峯神社的巴士方式。</li></ul><h2 id="旅遊建議" tabindex="-1">旅遊建議 <a class="header-anchor" href="#旅遊建議" aria-label="Permalink to “旅遊建議”">​</a></h2><ul><li>市區景點可由秩父站、御花畑站與西武秩父站步行串聯；前往山區景點前，請先確認巴士班次。</li><li>羊山公園芝櫻通常在 4 月中旬至 5 月上旬進入花期，實際花況與入園安排每年會變動。</li><li>秩父山區天氣與路況變化較快；冬季前往三峯神社自駕時，應確認道路資訊並準備冬季輪胎。</li></ul><h2 id="相關地區" tabindex="-1">相關地區 <a class="header-anchor" href="#相關地區" aria-label="Permalink to “相關地區”">​</a></h2><ul><li><strong><a href="./../../東京/">東京</a>：</strong> 從東京池袋可搭乘西武鐵道特急前往西武秩父。</li></ul><h2 id="相關連結" tabindex="-1">相關連結 <a class="header-anchor" href="#相關連結" aria-label="Permalink to “相關連結”">​</a></h2>',15)),a("ul",null,[a("li",null,[i(r,{url:"https://navi.city.chichibu.lg.jp/",placeHolderTitle:"秩父觀光なび（秩父市官方）"})]),a("li",null,[i(r,{url:"https://www.chichibuji.gr.jp/",placeHolderTitle:"秩父觀光協會"})])])])}const b=l(h,[["render",d]]);export{g as __pageData,b as default};
